export function FileCard({
  name = "{{name}}",
  size = "{{size}}",
  kind = "{{kind}}",
  showActions = {{showActions}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "14px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 300, padding: "12px 14px", borderRadius: 10, boxSizing: "border-box", display: "flex", alignItems: "center", gap: 12, border: "1px solid #24143018" }}>
      <span style={{ flex: "none", width: 36, height: 36, borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center", color: "#14351f", background: accent }}>
        <svg width="20" height="20" viewBox="0 0 20 20" aria-hidden="true"><path d="M5 2h7l4 4v12H5V2Z" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinejoin="round" /><path d="M12 2v4h4" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinejoin="round" /></svg>
      </span>
      <div style={{ flex: "1 1 auto", minWidth: 0 }}>
        <p style={{ margin: 0, fontWeight: 700, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{name}</p>
        <p style={{ margin: "2px 0 0", fontSize: 12, color: "#24143099" }}>{kind} &middot; {size}</p>
      </div>
      {showActions && <button type="button" aria-label={`More actions for ${name}`} style={{ flex: "none", border: "none", background: "none", cursor: "pointer", fontSize: 16, color: "#24143099", padding: "4px 8px", borderRadius: 6 }}>&#8942;</button>}
    </div>
  );
}
